  "구조화": "/audio/v1/ko-def92881.mp3",
  "구체적인 관습에 접근해서 설명하고, 상호 이해와 포용의 태도를 가지면 좋아요. 서로 다른 방식이 공존할 수 있다는 점도 인정하고요. 두 문화의 유사한 점을 찾는 것도 도움이 돼요.": "/audio/v1/ko-de69f712.mp3",
  "구체적인 대책을 요구했어요. 상황이 악화되면서 공사가 장기화됐지만, 대화를 통해 우선순위를 정할 수 있었어요. 문제에 직면했다고 끝나지 않아요.": "/audio/v1/ko-4a3b43bc.mp3",
  "구체적인 예가 글의 설득력을 높였어요.": "/audio/v1/ko-031c9a34.mp3",
  "구체적인 예시를 하나 들어 주세요.": "/audio/v1/ko-5cee6431.mp3",
  "구체적인 유보는 평가를 약하게 만들지 않고, 오히려 판단의 근거를 드러낸다.": "/audio/v1/ko-58e2ba44.mp3",
