  "국내 여행을 자주 해요.": "/audio/v1/ko-f77f9825.mp3",
  "국내선": "/audio/v1/ko-15035fd6.mp3",
  "국내선은 다른 건물이에요.": "/audio/v1/ko-7be1be31.mp3",
