  "군더더기": "/audio/v1/ko-c8aa720e.mp3",
  "군더더기를 덜어 내면 핵심 문장이 먼저 보인다.": "/audio/v1/ko-699c83ea.mp3",
  "군더더기를 덜어 내자 문단의 밀도가 높아졌어요.": "/audio/v1/ko-b2ee2643.mp3",
