  "궁물": "/audio/v1/ko-85cd3f31.mp3",
  "궁색하다": "/audio/v1/ko-05af3d40.mp3",
  "권고": "/audio/v1/ko-32d87a84.mp3",
  "권고안": "/audio/v1/ko-5119608d.mp3",
  "권력에는 견제가 필요하다는 원칙이 있어요.": "/audio/v1/ko-ff7afaf4.mp3",
  "권리": "/audio/v1/ko-40945fbe.mp3",
  "권리와 책임을 함께 생각해야 해요.": "/audio/v1/ko-18ac23bf.mp3",
  "권한": "/audio/v1/ko-12737517.mp3",
