  "꽃이 예뻐요.": "/audio/v1/ko-ef449254.mp3",
  "꾸준한 노력이 필요해요.": "/audio/v1/ko-6dcd59f0.mp3",
  "꾸준한 지속력이 필요해요.": "/audio/v1/ko-4d0061be.mp3",
