  "끝나다": "/audio/v1/ko-f97555b3.mp3",
  "나": "/audio/v1/ko-4dd619e0.mp3",
  "나 기다렸잖아. 왜 연락 안 했어?": "/audio/v1/ko-6498212c.mp3",
  "나가다": "/audio/v1/ko-080c48f8.mp3",
  "나는 같은 내용을 두 문장으로 풀어썼다.": "/audio/v1/ko-39a7c0b2.mp3",
  "나는 동료들을 대변할 자격이 없다고 말했다.": "/audio/v1/ko-98d77839.mp3",
  "나는 마지막 장면에서 명주가 배를 탔다고 읽었어.": "/audio/v1/ko-c94c1a0b.mp3",
  "나는 아니라고 봤어. 표를 쓰레기통에 버렸잖아.": "/audio/v1/ko-77870000.mp3",
  "나는 우리 집단을 대변할 수 없고, 내가 본 것만 말할 수 있다.": "/audio/v1/ko-0f74b784.mp3",
  "나는 이 글에서 도시의 고요함을 다시 생각하고자 한다.": "/audio/v1/ko-36a97dee.mp3",
  "나는 한국어를 잘한다는 칭찬을 자주 받는데, 그게 칭찬인지 확인인지 모르겠어.": "/audio/v1/ko-0f331ebf.mp3",
  "나는 회의실에 직접 들어가지 않았고, 복도에서 나오는 사람들의 표정만 보았다.": "/audio/v1/ko-99f7a5a6.mp3",
  "나도. 내가 브라질에서 왔다고 하면 삼바를 아느냐고 물어. 그건 내 경험이 아니라 정형화된 이미지잖아.": "/audio/v1/ko-c20b057a.mp3",
  "나라": "/audio/v1/ko-624f8e48.mp3",
  "나만큼 모른다고 생각해. 대신 장면화가 아주 구체적이라서 빈틈을 상상하게 돼.": "/audio/v1/ko-c43c8b78.mp3",
