  "나이": "/audio/v1/ko-5afc14dd.mp3",
  "나이가 몇 살이에요?": "/audio/v1/ko-a106b1d6.mp3",
  "나타나다": "/audio/v1/ko-56398123.mp3",
  "낚시": "/audio/v1/ko-d6091829.mp3",
  "난감하다": "/audio/v1/ko-8286be7e.mp3",
  "난이도": "/audio/v1/ko-b39a8edd.mp3",
  "난이도를 낮추되 결론의 한계는 남겼다.": "/audio/v1/ko-ed6af9af.mp3",
  "난처하다": "/audio/v1/ko-b851d006.mp3",
  "날씨": "/audio/v1/ko-3bf19400.mp3",
  "날씨가 좋으면 산에 가고, 아니면 영화관에 가요.": "/audio/v1/ko-4bbdd414.mp3",
  "날씨가 좋으면 산에 가요.": "/audio/v1/ko-cade1b6c.mp3",
  "날씨가 좋은 한 야외 일정을 유지할 거예요.": "/audio/v1/ko-a4fb1ab5.mp3",
  "날씨가 큰 변수예요.": "/audio/v1/ko-b78abc02.mp3",
  "날씨는 좋았어요?": "/audio/v1/ko-98051226.mp3",
  "날씬하다": "/audio/v1/ko-88bd9ff8.mp3",
  "날짜": "/audio/v1/ko-b1824837.mp3",
  "날카로운 지적에도 동요하지 않고 답했어요.": "/audio/v1/ko-43012470.mp3",
  "남은 과제는 인용의 정확도이며, 다음 학기에는 인용마다 전거를 표시할 계획이다.": "/audio/v1/ko-d91bab0b.mp3",
  "남은 사람만 조사하면 평균이 높아 보이는 맹점이 생긴다.": "/audio/v1/ko-c703b42c.mp3",
  "납득하다": "/audio/v1/ko-044b75d0.mp3",
