  "녕": "/audio/v1/ko-5ae77778.mp3",
  "노골적": "/audio/v1/ko-9489d8fb.mp3",
  "노골적인 비난은 관계를 회복하기 어렵게 만든다.": "/audio/v1/ko-e5f195af.mp3",
  "노래": "/audio/v1/ko-89b385da.mp3",
  "노래하다": "/audio/v1/ko-ec0474f6.mp3",
  "노력": "/audio/v1/ko-eb4151c3.mp3",
  "노력하면 성공할 거예요.": "/audio/v1/ko-7cd712e7.mp3",
  "노선": "/audio/v1/ko-849c69b5.mp3",
  "노트": "/audio/v1/ko-8c3374a4.mp3",
  "노트에 단어를 써요.": "/audio/v1/ko-a8e9e0de.mp3",
  "녹지 공간이 축소됐어요.": "/audio/v1/ko-e0932d5e.mp3",
  "녹지 면적이 늘어날수록 야간 기온의 상승 폭이 줄어드는가, 입니다.": "/audio/v1/ko-d8386939.mp3",
  "논객": "/audio/v1/ko-85fcfb64.mp3",
  "논객마다 같은 사안을 다른 가치로 해석했어요.": "/audio/v1/ko-9815041f.mp3",
  "논거": "/audio/v1/ko-34fa3d4a.mp3",
  "논거가 부족하면 설득하기 어려워요.": "/audio/v1/ko-862fe448.mp3",
  "논란": "/audio/v1/ko-832a5e66.mp3",
  "논란과 반응이 이어졌어요. 어떤 기사는 주민 편에, 어떤 기사는 시 편에 섰어요.": "/audio/v1/ko-df2bce09.mp3",
