  "바다 마을에 갔는데 골목이 낯익더라고요. 예전에 본 사진이 떠올랐어요.": "/audio/v1/ko-a377ba3f.mp3",
  "바다가 생각보다 넓더라고요.": "/audio/v1/ko-10e2fa24.mp3",
