  "바닥": "/audio/v1/ko-dffab2fb.mp3",
  "바닥에 가방이 있어요.": "/audio/v1/ko-e3cfec19.mp3",
  "바람": "/audio/v1/ko-fccb826d.mp3",
  "바람이 불어요.": "/audio/v1/ko-60187ce9.mp3",
  "바람이 유리창을 두드리는 듯했다.": "/audio/v1/ko-68da0a69.mp3",
