  "바로": "/audio/v1/ko-6ac24dd2.mp3",
  "바로 그 표현이 문제예요. 사실을 말하는 것 같지만, 사고의 원인을 학생 쪽으로 옮겨 놓죠.": "/audio/v1/ko-ab2a540a.mp3",
  "바로 그게 문제예요. 반복은 진행이 아니에요. 넷째 문단은 반론에 답하고, 남은 질문을 결론으로 이어야 해요.": "/audio/v1/ko-59453f6b.mp3",
  "바로 그게 좋은 합성이에요. 세 목소리를 하나로 만들지 않고, 각각의 자리를 남기는 거죠.": "/audio/v1/ko-ad476b5e.mp3",
  "바로 앞 문장에 사서 배치 확대도 있어서 후보가 둘이에요.": "/audio/v1/ko-05567944.mp3",
  "바로 확인해 드리겠습니다.": "/audio/v1/ko-007c4f84.mp3",
  "바른 자세로 앉으세요.": "/audio/v1/ko-6ee39eb2.mp3",
  "바블": "/audio/v1/ko-208980c3.mp3",
  "바쁘고 피곤해요": "/audio/v1/ko-a2f03c0c.mp3",
