  "발표 잘 들었어요. 그런데 설명 의무가 기업 비용을 너무 키우지 않을까요?": "/audio/v1/ko-848ca4ba.mp3",
  "발표 전에 같이 확인해야 해요.": "/audio/v1/ko-f564ba0e.mp3",
