  "발표의 첫 문장은 연구 질문이어야 하며, 방법은 그 질문에 어떻게 답했는지를 설명해야 한다.": "/audio/v1/ko-6a6e17b9.mp3",
  "발표자는 결론의 단정을 완화했어요.": "/audio/v1/ko-3bdaaf62.mp3",
  "발표자는 논문의 중심 명제를 첫 문단에서 분명히 밝혔어요.": "/audio/v1/ko-bdba5f03.mp3",
  "발표자는 요구 사항을 정리하며 글을 매듭지었다.": "/audio/v1/ko-d535dcde.mp3",
  "발표자는 자기 견해를 차분히 개진했어요.": "/audio/v1/ko-d6986d8f.mp3",
