  "배우다": "/audio/v1/ko-313f64b6.mp3",
  "배움은 끝이 아니라 계속되는 선택이라고 생각해요. 부족한 점을 인정하고, 다음에 다시 시도하면 됩니다.": "/audio/v1/ko-ac187dce.mp3",
