  "숫자는 맞을 수 있어요. 문제는 누가 빠졌는지입니다. 지난 석 달 안에 그만둔 배달원은 표본에서 빠졌어요.": "/audio/v1/ko-d3f7d272.mp3",
  "숫자는 사실이지만, 최악이라는 표현은 의견이라고 볼 수 있어요.": "/audio/v1/ko-e63a4612.mp3",
  "숫자는 중요하지만, 그들이 왜 익명을 요구했는지도 확인해야 해요.": "/audio/v1/ko-7450b158.mp3",
  "숫자는 중요하지만, 그들이 왜 익명을 요구했는지도 확인해야 해요. 탐사보도처럼 문서의 한계도 밝혀야 하고요.": "/audio/v1/ko-bd01aca2.mp3",
  "숫자는 집단의 분포를 보여 주는 반면, 그 분포의 이유는 설명하지 못한다.": "/audio/v1/ko-0ae4a5c9.mp3",
  "숫자는 하나만 남기고, 대신 무엇을 비교했는지와 한계를 함께 말씀해 주세요. 주민들이 조건을 이해할 수 있게 한 장짜리 설명 자료를 만들어 드릴게요.": "/audio/v1/ko-8fedf70a.mp3",
  "숫자만 보면 그렇게 말할 수 있지만, 모든 사람이 같은 이유로 사는 건 아니에요.": "/audio/v1/ko-077bcd48.mp3",
  "숫자만 보면 인과관계처럼 읽히니까요. 문제는 해석의 층위가 섞인다는 점이에요.": "/audio/v1/ko-1f70a4b6.mp3",
