  "신청 절차가 실제로 부정을 걸러 내는 핵심 장치라면 줄이기는 위험하다.": "/audio/v1/ko-3e2384fc.mp3",
  "신청 접수는 예정대로 진행하되, 대상자 선정 기준은 확정되는 대로 별도로 공지하겠습니다.": "/audio/v1/ko-14ff5947.mp3",
