  "아, 여기 있어요. 감사합니다.": "/audio/v1/ko-20e480a8.mp3",
  "아, 제가 본 사진에는 다 같이 웃으면서 일하는 모습만 있었어요.": "/audio/v1/ko-2dec3740.mp3",
  "아, 제가 요약하면서 표현을 단순화했어요.": "/audio/v1/ko-5f3edc61.mp3",
  "아, 좋아요. 이 사람은 선생님이에요?": "/audio/v1/ko-11234554.mp3",
  "아, 침대 옆에 있어요.": "/audio/v1/ko-773b6de3.mp3",
  "아나 씨, 다음 주 계획이 있어요?": "/audio/v1/ko-a6158ac6.mp3",
  "아나 씨, 메시지 확인해요.": "/audio/v1/ko-ad42cd15.mp3",
