  "아니요": "/audio/v1/ko-9b5997da.mp3",
  "아니요, 가끔 공부해요.": "/audio/v1/ko-be37df19.mp3",
  "아니요, 그런 뜻은 아니고요. 제가 보기에 단위가 바뀐 부분이 있어서요. 시간 되실 때 같이 볼 수 있을까요?": "/audio/v1/ko-ae7a77f6.mp3",
