  "아니요, 잘 못해요.": "/audio/v1/ko-9f81d404.mp3",
  "아니요, 저것은 안경이에요.": "/audio/v1/ko-c610ad9c.mp3",
  "아니요, 저는 버스로 가요.": "/audio/v1/ko-09a43186.mp3",
  "아니요, 저는 선생님이에요.": "/audio/v1/ko-a2d92e1b.mp3",
  "아니요, 저는 유학생이에요. 민수 씨는 회사원이에요?": "/audio/v1/ko-199074b4.mp3",
  "아니요. 2번은 예산을 조정하면 충분히 검토할 만해요. 다만 시범 지역을 넓히는 조건이 필요합니다.": "/audio/v1/ko-9ed18687.mp3",
  "아니요. 그 문장은 각주로 옮기세요. 삭제가 아니라 위치를 바꾸는 거예요.": "/audio/v1/ko-71d4b648.mp3",
  "아니요. 문제를 공론화하는 건 필요하지만, 검열로 해결할 일은 아니에요. “폭락”이라는 말은 “거래 감소”라는 뜻은 아니에요. 제목이 본문과 같은지 따져야 해요.": "/audio/v1/ko-7cdfae36.mp3",
  "아니요. 반대를 무시하고 강행하면 나중에 더 큰 갈등이 생겨요.": "/audio/v1/ko-2067c2fd.mp3",
  "아니요. 상관관계만으로 인과관계를 말할 수 없어요. 다른 변수가 있을 수 있거든요.": "/audio/v1/ko-aa813903.mp3",
  "아니요. 약국에 가자마자 약을 샀어요. 그리고 바로 회사로 갔어요.": "/audio/v1/ko-7a6a7794.mp3",
