  "인용문을 왜곡해서 보도했어요.": "/audio/v1/ko-aba6c181.mp3",
  "인용에는 반드시 원문의 위치를 함께 적어요.": "/audio/v1/ko-b0b345dd.mp3",
  "인용은 그대로 옮기고 밝히는 일이고, 바꿔 쓰기는 자기 문장으로 다시 쓰되 출처를 밝히는 일이다.": "/audio/v1/ko-ccc3b44d.mp3",
  "인용의 맥락을 확인하지 않은 데다가 전거도 밝히지 않아 신뢰를 잃었다.": "/audio/v1/ko-be526de5.mp3",
  "인용의 전거를 밝히는 일은 글의 신뢰를 지키는 최소한의 절차다.": "/audio/v1/ko-f3d3c4dd.mp3",
  "인용의 정확도예요. 인용마다 전거를 표시하고, 원문에서의 역할도 함께 적을 계획이에요.": "/audio/v1/ko-aa37a9cd.mp3",
