  "인정하다": "/audio/v1/ko-2342377d.mp3",
  "인정해요. 수익이 줄어든다는 점은 저희도 알고 있어요. 하지만 통로를 사유 공간으로 바꾸는 건 별개예요.": "/audio/v1/ko-c68c9a32.mp3",
