  "인터뷰 연구가 밝힌 바에 따르면, 청년은 일자리를 먼저 고려하는 동시에 가족과의 거리도 함께 계산한다.": "/audio/v1/ko-cde16a14.mp3",
  "인터뷰 연구가 밝힌 바에 따르면, 청년은 일자리를 우선 고려한다.": "/audio/v1/ko-22583a45.mp3",
  "인터뷰 연구는 지원이 있어도 일자리를 따라 이동하는 청년이 적지 않다고 본다.": "/audio/v1/ko-6c82206b.mp3",
  "인터뷰 인용문은 그대로 두고 행정적 보고에만 격식체를 적용한다.": "/audio/v1/ko-cb0523ef.mp3",
  "인터뷰 표본이 수도권에 치우친 데다가 응답률도 낮아 일반화가 어렵다.": "/audio/v1/ko-3fe1aeec.mp3",
  "인터뷰 한 건을 전체 여론으로 일반화해서는 안 된다.": "/audio/v1/ko-8c3fafff.mp3",
  "인터뷰는 경험을 듣는 데 그치지 않고, 제도의 빈틈을 드러냈다.": "/audio/v1/ko-52c9b7c5.mp3",
