  "좋은 인연을 소중히 여겨요.": "/audio/v1/ko-a573c31b.mp3",
  "좋은 자기평가는 점수가 아니라 근거와 다음 질문을 남긴다.": "/audio/v1/ko-05642a22.mp3",
  "좋은 작품이라고 해도 모두가 좋아하지는 않아요.": "/audio/v1/ko-7768d150.mp3",
  "좋은 작품이라고 해도 모든 사람이 좋아하지는 않아요.": "/audio/v1/ko-ecaac87a.mp3",
  "좋은 중재는 평행선을 감추지 않고, 어디까지가 합의이고 어디부터가 남은 문제인지 밝힌다.": "/audio/v1/ko-53c92568.mp3",
  "좋은 질문은 답이 아니라 무엇을 답할 수 있는지를 먼저 정한다.": "/audio/v1/ko-a89ef43a.mp3",
  "좋은 추억을 만들었어요.": "/audio/v1/ko-55ac050c.mp3",
  "좋은 통합은 두 방법을 같은 방향으로 정렬하는 일이 아니라, 각 방법이 대답할 수 있는 질문의 범위를 밝히는 일이다.": "/audio/v1/ko-65caf585.mp3",
