  "주민": "/audio/v1/ko-19216f26.mp3",
  "주민 설명회용으로 다시 쓴 글은 왜 넣었습니까?": "/audio/v1/ko-e05e917a.mp3",
  "주민 입장에서는 오전부터 차가 없어야 아이들이 안전합니다.": "/audio/v1/ko-7ad72f43.mp3",
  "주민과 시의 설명이 달라요. 주민은 소음이 심하다고 하고, 시는 기준을 지켰다고 해요.": "/audio/v1/ko-15d2b990.mp3",
