  "주민들이 설명회를 요구했어요.": "/audio/v1/ko-983dad20.mp3",
  "주민들이 조건을 이해할 수 있게 한 장짜리 자료를 만들었다.": "/audio/v1/ko-65488dbb.mp3",
  "주민들이 직접 참여하기도 해서 걱정이 적어요.": "/audio/v1/ko-19d880ba.mp3",
  "주민들이 직접 참여하기도 해요.": "/audio/v1/ko-0fa782a1.mp3",
