  "주의": "/audio/v1/ko-055f664d.mp3",
  "주인공을 '대범하다'고 옮기면 칭찬이지만, 문맥에 따라 '무책임하다'로 읽힐 수도 있겠어요.": "/audio/v1/ko-baa2c079.mp3",
