  "첫 번째 읽기에서는 문단마다 기능을 한 줄로 적었고, 두 번째 읽기에서는 연결을 봤어요.": "/audio/v1/ko-4f048a86.mp3",
  "첫 번째는 연설의 처음부터 미래를 말하고, 두 번째는 현재의 비용부터 말하죠.": "/audio/v1/ko-1a105fbd.mp3",
