  "하": "/audio/v1/ko-8bdbb59d.mp3",
  "하늘 씨, 우리가 은어를 쓴 건 아니에요. 그런데 모르는 말이 있으면 바로 물어봐 주세요.": "/audio/v1/ko-05131c48.mp3",
