  "하지만 상관성은 함께 변한다는 뜻이고, 인과성은 원인과 결과를 말해요.": "/audio/v1/ko-d5fbad6e.mp3",
  "하지만 아무 해석이나 되는 건 아니지. 배가 떠난 시각과 표의 날짜가 맞지 않는다는 점도 봐야 해.": "/audio/v1/ko-b727e675.mp3",
  "하지만 처음 연극을 보는 수용자에게는 필요한 선택이었을 수 있어.": "/audio/v1/ko-b114e21d.mp3",
