  "학술 발표에서는 근거의 출처를 분명히 밝혀야 해요.": "/audio/v1/ko-d7d5f26a.mp3",
  "학술 어휘의 정확성은 어려운 단어가 아니라 주장의 범위를 맞추는 데 있다.": "/audio/v1/ko-22e13b7f.mp3",
  "학술적 글쓰기에서 정확한 어휘는 장식이 아니라 주장의 범위를 정하는 장치다.": "/audio/v1/ko-d810bf8a.mp3",
