  "한 발 물러서서 협상했어요.": "/audio/v1/ko-b9317466.mp3",
  "한 번에 다 말하라고 하지 마세요. 기다리면 속마음을 털어놓을 거예요. 거짓말이 결국 들켰지만, 아나 씨를 속이고 싶지 않았대요. 그 점도 이해해 주세요.": "/audio/v1/ko-cea21a00.mp3",
