  "한 사람에게 보내는 글 안에서는 높임의 정도를 끝까지 유지해야 한다.": "/audio/v1/ko-eeda3948.mp3",
  "한 시간마다 한 번씩 일어나세요.": "/audio/v1/ko-a67545f4.mp3",
